import heapq

class LRI(dict):
    """
    The ``LRI`` implements the basic *Least Recently Inserted* strategy to
    caching. One could also think of this as a ``SizeLimitedDefaultDict``.
    """

    def __init__(self, max_size=DEFAULT_MAX_SIZE, values=None,
                 on_miss=None):
        super().__init__(values)
        self.max_size = max_size
        self.on_miss = on_miss
        self.hit_count = self.miss_count = self.soft_miss_count = 0
        self.heap = []

    def __setitem__(self, key, value):
        if key in self:
            self.hit_count += 1
        else:
            self.miss_count += 1
            if len(self) >= self.max_size:
                _, oldest_key = heapq.heappop(self.heap)
                del self[oldest_key]
        super().__setitem__(key, value)
        heapq.heappush(self.heap, (self.hit_count, key))

    def get(self, key, default=None):
        try:
            self.hit_count += 1
            return self[key]
        except KeyError:
            self.soft_miss_count += 1
            return default

    def pop(self, key, default=_MISSING):
        try:
            self.hit_count += 1
            return super().pop(key)
        except KeyError:
            if default is _MISSING:
                raise
            return default

    def __delitem__(self, key):
        super().__delitem__(key)
        self.heap = [(hit_count, key) for hit_count, key in self.heap if key != key]
```

