def read_entire_file(self):
    """Return the entire files contents."""
    self._checkClosed()
    pos = self.tell()
    self.seek(0)
    val = self.read()
    self.seek(pos)
    return val

def get_file_length(self):
    """Determine the length of the file"""
    pos = self.tell()
    if self._rolled:
        self.seek(0)
        val = os.fstat(self.fileno()).st_size
    else:
        self.seek(0, os.SEEK_END)
        val = self.tell()
    self.seek(pos)
    return val

def __next__(self):
    self._checkClosed()
    line = self.readline()
    if not line:
        pos = self.buffer.tell()
        self.buffer.seek(0, os.SEEK_END)
        if pos == self.buffer.tell():
            raise StopIteration
        else:
            self.buffer.seek(pos)
    return line

def seek_file(self, pos, mode=0):
    """Traverse from offset to the specified codepoint"""
    self._checkClosed()
    # Seek to position from the start of the file
    if mode == os.SEEK_SET:
        if pos < 0:
            raise ValueError("negative seek position")
        self.buffer.seek(0)
        self._traverse_codepoints(0, pos)
        self._tell = pos
    # Seek to new position relative to current position
    elif mode == os.SEEK_CUR:
        start_pos = self.tell()
        destination = start_pos + pos
        if destination < 0:
            raise ValueError("negative seek position")
        if pos < 0:
            # UTF-8 offsets count characters, so traverse from the start.
            return self.seek(destination)
        self._traverse_codepoints(start_pos, pos)
        self._tell = destination
    elif mode == os.SEEK_END:
        self.buffer.seek(0)
        dest_position = self.get_file_length() - pos
        self._traverse_codepoints(0, dest_position)
        self._tell = dest_position
    else:
        raise ValueError(
            f"Invalid whence ({mode}, should be 0, 1, or 2)"
        )
    return self.tell()

def buf(self):
    return self.read_entire_file()
