    """Descriptor class implementing the basic descriptor protocol."""

    def __init__(self, deprecated=False):
        self.__attrname = None
        self.__deprecated = deprecated
        self.__unbound = None

    def __set_name__(self, owner, name):
        if self.__attrname is None:
            self.__attrname = name
        elif name != self.__attrname:
            raise TypeError(
                "Cannot assign the same @cachedmethod to two different names "
                f"({self.__attrname} and {name})."
            )

    def __get__(self, obj, objtype=None):
        if obj is None:
            return self.__get_unbound()
        return self._get_descriptor(obj)

    def __get_unbound(self):
        if self.__unbound is None:
            self.__unbound = _Unbound(self)
        return self.__unbound

    def _get_descriptor(self, obj):
        wrapper = self._get_wrapper(obj)
        return wrapper

    def _get_wrapper(self, obj):
        wrapper = self._get_wrapper_from_instance(obj)
        if wrapper is None:
            wrapper = self._create_wrapper(obj)
        return wrapper

    def _get_wrapper_from_instance(self, obj):
        try:
            return obj.__dict__[self.__attrname]
        except (AttributeError, TypeError):
            return None

