        wrapper = self.Wrapper(obj)
        if self.__deprecated:
            self._warn_instance_dict(obj)
        else:
            raise TypeError(f"No '__dict__' attribute on {type(obj)} instance to cache {self.__attrname} property.")
        return wrapper

    def _warn_instance_dict(self, obj):
