    """Formats the help into a string and returns it."""
    self._format_usage(ctx, formatter)
    self._format_help_text(ctx, formatter)
    self._format_arguments(ctx, formatter)
    self._format_options(ctx, formatter)
    self._format_epilog(ctx, formatter)

def _format_usage(self, ctx: Context, formatter: HelpFormatter) -> None:
    """Formats the usage line into the formatter."""
    pieces = self.collect_usage_pieces(ctx)
    formatter.write_usage(ctx.command_path, " ".join(pieces))

def _format_help_text(self, ctx: Context, formatter: HelpFormatter) -> None:
    """Formats the help text into the formatter."""
    if self.help:
        help_text = inspect.cleandoc(self.help)
        formatter.write_paragraph(help_text)

def _format_arguments(self, ctx: Context, formatter: HelpFormatter) -> None:
    """Formats the arguments into the formatter."""
    if self.args:
        formatter.write_heading("Arguments:")
        for arg in self.args:
            formatter.write_text(f"{arg.opts[0]}: {arg.help}")

def _format_options(self, ctx: Context, formatter: HelpFormatter) -> None:
    """Formats the options into the formatter."""
    if self.options:
        formatter.write_heading("Options:")
        for opt in self.options:
            formatter.write_text(f"{opt.opts[0]}: {opt.help}")

def _format_epilog(self, ctx: Context, formatter: HelpFormatter) -> None:
    """Formats the epilog into the formatter."""
    if self.epilog:
        epilog = inspect.cleandoc(self.epilog)
        formatter.write_paragraph()
        with formatter.indentation():
            formatter.write_text(epilog)
