from ._compat import term_len

def iter_rows(rows: Iterable[Tuple[str, str]], n: int) -> Iterable[Tuple[str, str]]:
    """Iterate over rows, ensuring they have at least n columns."""
    for row in rows:
        if len(row) < n:
            row += ("",) * (n - len(row))
        yield row[:n]

def wrap_text(text: str, width: int, preserve_paragraphs: bool = False) -> str:
    """Wrap text to a given width, preserving paragraphs if requested."""
    if not preserve_paragraphs:
        return "\n".join(wrap(text, width))
    else:
        return "\n".join(["\n".join(wrap(paragraph, width)) for paragraph in text.split("\n")])

def write_dl(
    self,
    rows: Iterable[Tuple[str, str]],
    col_max: int = 30,
    col_spacing: int = 2,
) -> None:
    """Writes a definition list into the buffer.  This is how options
    and commands are usually formatted.

    :param rows: a list of two item tuples for the terms and values.
    :param col_max: the maximum width of the first column.
    :param col_spacing: the number of spaces between the first and
                        second column.
    """
    rows = list(iter_rows(rows, 2))
    widths = tuple(max(term_len(col) for col in row) for row in rows)
    if len(widths) != 2:
        raise TypeError("Expected two columns for definition list")

    first_col = min(widths[0], col_max) + col_spacing

    for first, second in iter_rows(rows, 2):
        self.write(f"{'':>{self.current_indent}}{first}")
        if not second:
            self.write("\n")
            continue
        if term_len(first) <= first_col - col_spacing:
            self.write(" " * (first_col - term_len(first)))
        else:
            self.write("\n")
            self.write(" " * (first_col + self.current_indent))

        text_width = max(self.width - first_col - 2, 10)
        wrapped_text = wrap_text(second, text_width, preserve_paragraphs=True)
        lines = wrapped_text.splitlines()

        if lines:
            self.write(f"{lines[0]}\n")

            for line in lines[1:]:
                self.write(f"{'':>{first_col + self.current_indent}}{line}\n")
        else:
            self.write("\n")
