class BlockParser(Parser[BlockState]):
    # ...

    def parse_fenced_code(self, m: Match[str], state: BlockState) -> Optional[int]:
        """Parse token for fenced code block."""
        spaces = m.group("fenced_1")
        marker = m.group("fenced_2")
        info = m.group("fenced_3")

        c = marker[0]
        if info and c == "`":
            if info.find(c) != -1:
                return None

        _end = self._create_end_regex(c, len(marker))
        cursor_start = m.end() + 1

        m2 = _end.search(state.src, cursor_start)
        code, end_pos = self._extract_code(state, cursor_start, m2)

        if spaces and code:
            code = self._trim_code(state, code, spaces)

        token = self._create_token(code, marker, info)
        state.append_token(token)
        return end_pos

    def _create_end_regex(self, c: str, length: int) -> Pattern[str]:
        return re.compile(r"^ {0,3}" + c + "{" + str(length) + r",}[ \t]*(?:\n|$)", re.M)

    def _extract_code(self, state: BlockState, cursor_start: int, m2) -> Tuple[str, int]:
        if m2:
            code = state.src[cursor_start : m2.start()]
            end_pos = m2.end()
        else:
            code = state.src[cursor_start:]
            end_pos = state.cursor_max
        return code, end_pos

    def _trim_code(self, state: BlockState, code: str, spaces: str) -> str:
        _trim_pattern = re.compile("^ {0," + str(len(spaces)) + "}", re.M)
        return _trim_pattern.sub("", code)

    def _create_token(self, code: str, marker: str, info: str) -> dict:
        token = {"type": "block_code", "raw": code, "style": "fenced", "marker": marker}
        if info:
            info = _ESCAPE_CHAR_RE.sub('\\1', info)
            token["attrs"] = {"info": info.strip()}
        return token
