        return parse_link_href(src, start_pos, block=block, max_nested_level=max_nested_level)

    def _find_next_blank_line(self, state: BlockState, start_pos: int, blank_line: str) -> Optional[int]:
        return state.find_next_blank_line(start_pos, blank_line)

    def _handle_title_position(self, src: str, title_pos: Optional[int]) -> Optional[int]:
        if title_pos is None:
            return None
        m = re.match(r"\n+", src[title_pos:])
        if m:
            title_pos += m.end()
        else:
            title_pos = None
        return title_pos
