```python
def _add_token(self, token):
    """
    This function handles the addition of tokens to the parsing stack.
    It manages the transition between states based on the token type.
    """
    grammar = self._pgen_grammar
    stack = self.stack
    token_type, value, start_pos, prefix = token
    transition = _token_to_transition(grammar, token_type, value)

    while True:
        try:
            plan = stack[-1].dfa.transitions[transition]
            break
        except KeyError:
            if stack[-1].dfa.is_final:
                self._handle_final_state(stack)
            else:
                self.error_recovery(token)
                return
        except IndexError:
            raise InternalParseError("too much input", token_type, value, start_pos)

    stack[-1].dfa = plan.next_dfa

    for push in plan.dfa_pushes:
        stack.append(StackNode(push))

    leaf = self.convert_leaf(token_type, value, prefix, start_pos)
    stack[-1].nodes.append(leaf)

def _handle_final_state(self, stack):
    tos = stack.pop()
    new_node = tos.nodes[0] if len(tos.nodes) == 1 else self.convert_node(tos.dfa.from_rule, tos.nodes)
    stack[-1].nodes.append(new_node)

def error_recovery(self, token):
    tos_nodes = self.stack[-1].nodes
    if tos_nodes:
        last_leaf = tos_nodes[-1].get_last_leaf()
    else:
        last_leaf = None

    if not self._error_recovery:
        return super().error_recovery(token)

    if self._start_nonterminal == 'file_input' and \
            (token.type == PythonTokenTypes.ENDMARKER
             or token.type == DEDENT and not last_leaf.value.endswith('\n')
             and not last_leaf.value.endswith('\r')):
        if self.stack[-1].dfa.from_rule == 'simple_stmt':
            try:
                plan = self.stack[-1].dfa.transitions[PythonTokenTypes.NEWLINE]
            except KeyError:
                pass
            else:
                if plan.next_dfa.is_final and not plan.dfa_pushes:
                    self.stack[-1].dfa = plan.next_dfa
                    self._add_token(token)
                    return

    self._handle_error_recovery(token)

def _handle_error_recovery(self, token):
    until_index = self._current_suite(self.stack)
    if self._stack_removal(until_index + 1):
        self._add_token(token)
    else:
        self._handle_error_token(token)

def _handle_error_token(self, token):
    typ, value, start_pos, prefix = token
    if typ == INDENT:
        self._omit_dedent_list.append(self._indent_counter)

    error_leaf = tree.PythonErrorLeaf(typ.name, value, start_pos, prefix)
    self.stack[-1].nodes.append(error_leaf)

def _current_suite(self, stack):
    for until_index, stack_node in reversed(list(enumerate(stack))):
        if stack_node.nonterminal == 'file_input':
            break
        elif stack_node.nonterminal == 'suite':
            if len(stack_node.nodes) != 1:
                break
    return until_index
