def _reset_newlines(self, spacing, leaf, is_comment=False):
    self._max_new_lines_in_prefix = max(self._max_new_lines_in_prefix, self._newline_count)

    wanted_blank_lines = self._get_wanted_blank_lines_count()
    if wanted_blank_lines is not None and self._newline_count - 1 < wanted_blank_lines:
        if not is_comment:
            self._add_missing_blank_lines_issue(spacing, wanted_blank_lines)
        self._wanted_newline_count = None

    self._newline_count = 0
    self._max_new_lines_in_prefix = 0

    if not is_comment and leaf.type != 'endmarker':
        self._check_blank_lines_after_function_or_class(spacing, leaf)

def _get_wanted_blank_lines_count(self):
    suite_node = self._indentation_tos.get_latest_suite_node()
    return int(suite_node.parent is None) + 1

def _add_missing_blank_lines_issue(self, spacing, wanted_blank_lines):
    code = 302 if wanted_blank_lines == 2 else 301
    message = "expected %s blank line, found %s" % (wanted_blank_lines, wanted_blank_lines - 1)
    self.add_issue(spacing, code, message)

def _check_blank_lines_after_function_or_class(self, spacing, leaf):
    val = leaf.value
    if val == '@' and leaf.parent.type == 'decorator':
        return

    if val in {'class', 'async'}:
        next_leaf = leaf.get_next_leaf()
        if next_leaf and next_leaf.value == 'def':
            return

    if val == 'def':
        prev_leaf = leaf.get_previous_leaf()
        if prev_leaf and prev_leaf.value == 'async':
            return

    suite_node = self._indentation_tos.get_latest_suite_node()
    if suite_node.parent is not None:
        return

    actual_blank_lines = self._max_new_lines_in_prefix - 1
    if actual_blank_lines < 1:
        return

    code = 302 if actual_blank_lines == 2 else 301
    message = "expected %s blank line, found %s" % (1, actual_blank_lines)
    self.add_issue(spacing, code, message)
