from enum import Enum
from typing import Literal, assert_never

# ...

class CLexer:
    ...

    def _attribute_arguments(self) -> Token | None:
        """Scan an attribute argument clause with _pos at its opening '('.

        Return one ATTRIBUTE_ARGUMENTS token containing the raw text inside
        the outer parentheses. A stack tracks the expected closing delimiters
        for nested (), [], and {}. Comments and quoted literals are skipped
        while balancing, but preserved in the token value. This bypasses normal
        token classification, keeping arbitrary attribute arguments separate
        from C expressions and scope tracking.

        Report malformed clauses at the opening parenthesis. If the error
        callback returns, consume the remaining input and return None.
        """
        text = self._lexdata
        start = self._pos
        pos = start + 1
        closers = [")"]
        pairs = {"(": ")", "[": "]", "{": "}"}
        error = "Unterminated attribute arguments"

        while pos < len(text):
            ch = text[pos]
            if self._is_comment(pos):
                pos = self._skip_comment(pos)
                continue
            if self._is_quote(ch):
                pos = self._skip_quote(ch, pos)
                continue
            if self._is_identifier_or_number(pos):
                pos = self._skip_identifier_or_number(pos)
                continue
            if ch in pairs:
                closers.append(pairs[ch])
            elif ch in ")]}":
                if ch != closers[-1]:
                    error = "Mismatched delimiter in attribute arguments"
                    break
                closers.pop()
                if not closers:
                    end2 = pos + 1
                    value = self._lexdata[self._pos:end2]
                    tok2 = self._make_token('ATTRIBUTE_ARGUMENTS', value, self._pos)
                    self._update_lineno_and_line_start(value)
                    self._pos = end2
                    tok = tok2
                    tok.value = tok.value[1:-1]
                    return tok
            pos += 1
        self._error(error, start)
        self._pos = len(text)
        return None

    def _is_comment(self, pos: int) -> bool:
        return self._lexdata.startswith("/*", pos) or self._lexdata.startswith("//", pos)

    def _skip_comment(self, pos: int) -> int:
        if self._lexdata.startswith("/*", pos):
            return self._lexdata.find("*/", pos + 2) + 2
        if self._lexdata.startswith("//", pos):
            return min(self._lexdata.find("\n", pos + 2), len(self._lexdata))
        return pos

    def _is_quote(self, ch: str) -> bool:
        return ch in {"'", '"'}

    def _skip_quote(self, quote: str, pos: int) -> int:
        pos += 1
        while pos < len(self._lexdata) and self._lexdata[pos] not in {quote, "\n"}:
            pos += 2 if self._lexdata[pos] == "\\" else 1
        return pos + 1 if pos < len(self._lexdata) and self._lexdata[pos] == quote else pos

    def _is_identifier_or_number(self, pos: int) -> bool:
        return _attribute_word.match(self._lexdata, pos) is not None

    def _skip_identifier_or_number(self, pos: int) -> int:
        match = _attribute_word.match(self._lexdata, pos)
        return match.end() if match else pos

    def _update_lineno_and_line_start(self, value: str) -> None:
        self._lineno += value.count('\n')
        if '\n' in value:
            self._line_start = self._pos + value.rfind('\n') + 1

    def _make_token(self, token_type: str, value: str, pos: int) -> Token:
        return Token(token_type, value, (self._filename, self._lineno, pos, pos + len(value)))

    def _error(self, error: str, pos: int) -> None:
        if self._error_func:
            self._error_func(self._filename, self._lineno, pos, error)
