            name=None,
            quals=spec["qual"],
            storage=spec["storage"],
            type=decl["decl"],
            coord=decl["decl"].coord,
        )

    def _create_normal_declaration(
        self, spec: "_DeclSpec", decl: "_DeclInfo"
    ) -> c_ast.Decl:
