def _parse_decl_suffixes(self, decl: c_ast.Node) -> c_ast.Node:
    """Parse a chain of array/function suffixes and attach them to decl."""
    while True:
        if self._peek_type() == "LBRACKET":
            decl = self._parse_array_decl(decl)
        elif self._peek_type() == "LPAREN":
            decl = self._parse_function_decl(decl)
        else:
            break
    return decl

def _parse_array_decl(self, base_decl: c_ast.Node) -> c_ast.Node:
    """Parse an array declarator suffix and return an ArrayDecl node."""
    self._expect("LBRACKET")
    dim = self._parse_assignment_expression() if self._starts_expression() else None
    self._expect("RBRACKET")
    return self._build_array_decl(base_decl, dim)

def _parse_function_decl(self, base_decl: c_ast.Node) -> c_ast.Node:
    """Parse a function declarator suffix and return a FuncDecl node."""
    self._expect("LPAREN")
    if self._accept("RPAREN"):
        args = None
    else:
        args = self._parse_parameter_type_list() if self._starts_declaration() or self._peek_type() == "ELLIPSIS" else self._parse_identifier_list_opt()
        self._expect("RPAREN")
    func = c_ast.FuncDecl(args=args, type=None, coord=base_decl.coord, attributes=self._parse_attribute_specifier_sequence())
    return self._build_function_decl(base_decl, func)

def _build_array_decl(self, base_decl: c_ast.Node, dim: c_ast.Node) -> c_ast.Node:
    """Build an ArrayDecl node from a base declarator and a dimension."""
    array_decl = c_ast.ArrayDecl(type=base_decl, dim=dim, coord=base_decl.coord, attributes=self._parse_attribute_specifier_sequence())
    return self._type_modify_decl(base_decl, array_decl)

def _build_function_decl(self, base_decl: c_ast.Node, func: c_ast.Node) -> c_ast.Node:
    """Build a FuncDecl node from a base declarator and a function declarator."""
    func_decl = c_ast.FuncDecl(args=func.args, type=None, coord=base_decl.coord, attributes=self._parse_attribute_specifier_sequence())
    return self._type_modify_decl(base_decl, func_decl)
