# BNF: direct_abstract_declarator : '(' abstract_declarator ')'
#                                  | direct_abstract_declarator '[' ... ']'
#                                  | direct_abstract_declarator '(' ... ')'
def _parse_direct_abstract_declarator(self) -> c_ast.Node | None:
    if self._accept("LPAREN"):
        decl = self._parse_abstract_declarator()
        self._expect("RPAREN")
        return decl
    base_decl = self._parse_direct_abstract_declarator()
    if self._peek_type() == "LBRACKET":
        return self._type_modify_decl(base_decl, self._parse_array_decl(base_decl))
