        self._expect('LPAREN')
        if self._accept('RPAREN'):
            args = None
        else:
            args = self._parse_parameter_type_list() if self._starts_declaration() or self._peek_type() == 'ELLIPSIS' else self._parse_identifier_list_opt()
            self._expect('RPAREN')
        return self._type_modify_decl(base_decl, c_ast.FuncDecl(args=args, type=None, coord=base_decl.coord, attributes=self._parse_attribute_specifier_sequence()))
    return base_decl

# BNF: abstract_declarator_opt : abstract_declarator | empty
def _parse_abstract_declarator_opt(self) -> c_ast.Node | None:
    if self._peek_type() == "LPAREN" or self._peek_type() == "TIMES":
        return self._parse_abstract_declarator()
