def compile_source_to_ast(code_string, filename):
    try:
        return ast.parse(code_string, filename=filename)
    except SyntaxError as e:
        reporter.syntaxError(filename, e.args[0], e.lineno, e.offset, e.text)
        return 1
    except Exception:
