def handle_syntax_error(codeString, filename, reporter):
    """
    Handle syntax errors in the Python source given by C{codeString}.

    @param codeString: The Python source to check.
    @type codeString: C{str}

    @param filename: The name of the file the source came from, used to report
        errors.
    @type filename: C{str}

    @param reporter: A L{Reporter} instance, where errors and warnings will be
        reported.

    @return: True if there is a syntax error, False otherwise.
    @rtype: C{bool}
    """
    try:
        tree = ast.parse(codeString, filename=filename)
    except SyntaxError as e:
        reporter.syntaxError(filename, e.args[0], e.lineno, e.offset, e.text)
        return True
    except Exception:
        reporter.unexpectedError(filename, 'problem decoding source')
        return True
    return False


def check(codeString, filename, reporter=None):
    """
    Check the Python source given by C{codeString} for flakes.

    @param codeString: The Python source to check.
    @type codeString: C{str}

    @param filename: The name of the file the source came from, used to report
        errors.
    @type filename: C{str}

    @param reporter: A L{Reporter} instance, where errors and warnings will be
        reported.

    @return: The number of warnings emitted.
    @rtype: C{int}
    """
    if reporter is None:
        reporter = Reporter(sys.stdout, sys.stderr)

    if handle_syntax_error(codeString, filename, reporter):
        return 1

    # Okay, it's syntactically valid.  Now check it.
    w = checker.Checker(ast.parse(codeString, filename=filename), filename=filename)
    w.messages.sort(key=lambda m: m.lineno)
    for warning in w.messages:
        reporter.flake(warning)
    return len(w.messages)
```
