import os
import sys
from pyflakes import checker, __version__
from pyflakes import reporter as modReporter
from pyflakes.reporter import Reporter

def _read_file(filename):
    """
    Read a file and return its content as a string.

    @param filename: The name of the file to read.
    @return: The content of the file as a string.
    """
    try:
        with open(filename, 'rb') as f:
            return f.read()
    except OSError as e:
        raise IOError(f"Error reading file {filename}: {e.args[1]}")

def _make_reporter(warning_stream=None, error_stream=None):
    """
    Make a reporter that can be used when no reporter is specified.

    @param warning_stream: A file-like object where warnings will be
        written to.  The stream's C{write} method must accept unicode.
        C{sys.stdout} is a good value.
    @param error_stream: A file-like object where error output will be
        written to.  The stream's C{write} method must accept unicode.
        C{sys.stderr} is a good value.
    """
    warning_stream = warning_stream or sys.stdout
    error_stream = error_stream or sys.stderr
    return Reporter(warning_stream, error_stream)

def check_path(filename, reporter=None):
    """
    Check the given path, printing out any warnings detected.

    @param filename: The name of the file to check.
    @param reporter: A L{Reporter} instance, where errors and warnings will be
        reported.

    @return: the number of warnings printed
    """
    reporter = reporter or _make_reporter()
    codestr = _read_file(filename)
    return checker.check(codestr, filename, reporter)
