import ast
import collections
import contextlib
import functools
import sys

from pyflakes import messages
from pyflakes.common import (
    Assignment,
    ClassDefinition,
    FunctionDefinition,
    GeneratorScope,
    ComprehensionScope,
    Importation,
    ImportationFrom,
    StarImportation,
    FutureImportation,
    SubmoduleImportation,
    VariableKey,
    convert_to_value,
    iter_dict_children,
    is_notimplemented_name_node,
    parse_percent_format,
    getNodeName,
    _is_typing,
    _is_const_non_singleton,
)


class Checker:
    def FUNCTIONDEF(self, node):
        self._handle_function_definition(node)

    def _handle_function_definition(self, node):
        for deco in node.decorator_list:
            self.handleNode(deco, node)

        with self._type_param_scope(node):
            self.LAMBDA(node)

        self.addBinding(node, FunctionDefinition(node.name, node))
        self._handle_doctests(node)

    def _handle_doctests(self, node):
        if (
            self.withDoctest
            and not self._in_doctest()
            and not isinstance(self.scope, FunctionScope)
        ):
            callable = functools.partial(self.handleDoctests, node)
            self._deferred.append((callable, self.scopeStack[:], self.offset))

    def LAMBDA(self, node):
        self._handle_lambda(node)

    def _handle_lambda(self, node):
        args, annotations = self._get_lambda_args_and_annotations(node)

        for annotation in annotations:
            self.handleAnnotation(annotation, node)

        self._handle_lambda_args(args, node)
        self._handle_lambda_body(node)

    def _get_lambda_args_and_annotations(self, node):
        args = []
        annotations = []

        for arglist in (
            node.args.posonlyargs,
            node.args.args,
            node.args.kwonlyargs,
        ):
            for arg in arglist:
                args.append(arg.arg)
                annotations.append(arg.annotation)

        defaults = node.args.defaults + node.args.kw_defaults
        wildcards = (node.args.vararg, node.args.kwarg)

        for wildcard in wildcards:
            if wildcard is not None:
                args.append(wildcard.arg)
                annotations.append(wildcard.annotation)

        if not isinstance(node, ast.Lambda):
            annotations.append(node.returns)

        return args, annotations

    def _handle_lambda_args(self, args, node):
        if len(set(args)) < len(args):
            self._report_duplicate_arguments(args, node)

    def _report_duplicate_arguments(self, args, node):
        for (idx, arg) in enumerate(args):
            if arg in args[:idx]:
                self.report(messages.DuplicateArgument, node, arg)

    def _handle_lambda_body(self, node):
        def runFunction():
            with self.in_scope(FunctionScope):
                self.handleChildren(
                    node,
                    omit=('decorator_list', 'returns', 'type_params'),
                )

        self.deferFunction(runFunction)
