class Checker:
    def __init__(self, tree, filename='(none)', builtins=None,
                 with_doctest='PYFLAKES_DOCTEST' in os.environ):
        self._initialize_attributes(tree, filename, builtins, with_doctest)
        self._run_deferred()
        self.check_dead_scopes()

    def _initialize_attributes(self, tree, filename, builtins, with_doctest):
        self._node_handlers = {}
        self._parents = {}
        self._node_depths = {}
        self._deferred = collections.deque()
        self.dead_scopes = []
        self.messages = []
        self.filename = filename
        self.built_ins = builtins or builtins.builtin_vars() | _custom_builtins()
        self.with_doctest = with_doctest
        self.except_handlers = [()]
        self.root = tree

        self.scope_stack = []
        scope_tp = Checker._ast_node_scope[type(tree)]

        with self.in_scope(scope_tp):
            for builtin in self.built_ins:
                self.add_binding(None, Builtin(builtin))
            for node in iter_child_nodes(tree, omit=None):
                self.handle_node(node, tree)

    def _run_deferred(self):
        while self._deferred:
            func = self._deferred.popleft()
            func()

    def check_dead_scopes(self):
        for scope in self.dead_scopes:
            if scope.is_used:
                self.report(messages.UndefinedName, scope.node, scope.node_lineno)
