import ast
import re
from pyflakes import messages

def get_docstring(node):
    """
    Extracts the docstring from a node.

    @param node: The node to extract the docstring from.
    @return: A tuple containing the docstring and the line number of the first line of the docstring.
    """
    if not hasattr(node, 'body'):
        return None, None

    for child in node.body:
        if isinstance(child, ast.Expr) and isinstance(child.value, ast.Str):
            return child.value.s, child.lineno

    return None, None

def parse_doctest(docstring):
    """
    Parses a doctest string.

    @param docstring: The doctest string to parse.
    @return: A list of doctest examples.
    """
    if not docstring:
        return []

    examples = []
    for match in re.finditer(r'^\s*>>>\s*(.*)$', docstring, re.MULTILINE):
        source = match.group(1).strip()
        examples.append(source)

    return examples

def handle_doctests(self, node):
    """
    Handles doctests in a node.

    @param node: The node to handle the doctests in.
    """
    docstring, node_lineno = get_docstring(node)
    if not docstring:
        return

    examples = parse_doctest(docstring)
    if not examples:
        return

    # Place doctest in module scope
    saved_stack = self.scopeStack
    self.scopeStack = [self.scopeStack[0]]
    node_offset = self.offset or (0, 0)
    with self.in_scope(DoctestScope):
        if '_' not in self.scopeStack[0]:
            self.addBinding(None, Builtin('_'))
        for example in examples:
            try:
                tree = ast.parse(example, "<doctest>")
            except SyntaxError as e:
                position = (node_lineno + e.lineno, e.offset or 0)
                self.report(messages.DoctestSyntaxError, node, position)
            else:
                self.offset = (node_offset[0] + node_lineno, node_offset[1])
                for node2 in iter_child_nodes(tree, omit=None):
                    self.handleNode(node2, tree)
                self.offset = node_offset
    self.scopeStack = saved_stack
