def _get_docstring(node):
    if hasattr(node, 'body') and len(node.body) > 0:
        if isinstance(node.body[0], ast.Expr) and hasattr(node.body[0], 'value') and isinstance(node.body[0].value, ast.Str):
            return node.body[0].value.s, node.body[0].lineno
    return None, None

