    except SyntaxError as e:
        position = (node.lineno + e.lineno, node.indent + 4 + (e.offset or 0))
        _report_syntax_error(self, node, position)
    else:
        self.offset = (node_offset[0] + node.lineno, node_offset[1] + node.indent + 4)
        for node2 in iter_child_nodes(tree, omit=None):
