class SymbolFilter(Filter):
    """
    Replaces special symbols with their corresponding Unicode characters.

    Options accepted:

    `lang` : str
       The language to use. Must be one of 'isabelle' or 'latex'. The default is 'isabelle'.
    """

    def __init__(self, **options):
        Filter.__init__(self, **options)
        allowed = ['isabelle', 'latex']
        string = options.get('lang', 'isabelle')
        if string not in allowed:
            raise OptionError(f"Value for option 'lang' must be one of {', '.join(map(str, allowed))}")
        lang = string
        self.symbols = self.lang_map[lang]

    def filter(self, lexer, stream):
        for ttype, value in stream:
            if value in self.symbols:
                yield ttype, self.symbols[value]
            else:
                yield ttype, value
