    r = (rgb >> 16) & 0xff
    g = (rgb >> 8) & 0xff
    b = rgb & 0xff
    return (r, g, b)

def _get_closest_color(self, r, g, b):
    distance = 257 * 257 * 3
    match = 0
    for i in range(0, 256):
        values = self.xterm_colors[i]
        rd = r - values[0]
        gd = g - values[1]
        bd = b - values[2]
        d = rd * rd + gd * gd + bd * bd
        if d < distance:
            match = i
            distance = d
    return match
