def _align_cell_veritically(cell_lines, num_lines, width, alignment):
    return (cell_lines + [" " * width] * (num_lines - len(cell_lines))) if alignment == "top" \
        else ([" " * width] * (num_lines - len(cell_lines)) + cell_lines) if alignment == "bottom" \
        else ([" " * math.ceil((width - len(cell_lines[i])) / 2) + cell_lines[i] +
               " " * math.floor((width - len(cell_lines[i])) / 2)
               for i in range(num_lines)])


def _pad_row(row, pad):
    return [" " * pad + cell + " " * pad for cell in row]


