from tomlkit.items import Item, Trivia

class Array(Item, list):
    """
    An array literal
    """

    def __init__(
        self, value: list[Item], trivia: Trivia, multiline: bool = False
    ) -> None:
        super().__init__(self._filter_values(value))
        self._trivia = trivia
        self._multiline = multiline

    def _filter_values(self, value: list[Item]) -> list[Item]:
        """Filter out whitespace and comment items"""
        return [v for v in value if not isinstance(v, (Whitespace, Comment, Null))]

    def unwrap(self) -> list[Any]:
        return [v.unwrap() if hasattr(v, "unwrap") else v for v in self]

    @property
    def discriminant(self) -> int:
        return 8

    @property
    def value(self) -> list[Item]:
        return self

    def multiline(self, multiline: bool) -> Array:
        """Change the array to display in multiline or not."""
        self._multiline = multiline
        return self

    def as_string(self) -> str:
        if not self._multiline or not self:
            return f"[{', '.join(v.as_string() for v in self)}]"

        s = "[\n"
        s += "".join(
            f"{v.value.as_string()}," if not isinstance(v.value, Null) else ""
            for v in self
        )
        s += "\n]"

        return s

    def add_line(
        self,
        *items: Any,
        indent: str = "    ",
        comment: Optional[str] = None,
        add_comma: bool = True,
        newline: bool = True,
    ) -> None:
        """Add multiple items in a line to control the format precisely."""
        if comment and ("\n" in comment or "\r" in comment):
            raise ValueError("Comment cannot contain line breaks")

        if newline:
            indent += "\n"

        for item in items:
            it = item(item)
            if add_comma:
                self.append(it)
                self.append(Whitespace(","))
            else:
                self.append(it)

        if comment:
            self.append(Comment(Trivia(indent=indent, comment=f"# {comment}", trail="")))

    def _getstate(self, protocol: int = 3) -> tuple[list[Item], Trivia, bool]:
        return self, self._trivia, self._multiline
